const schema = [{"@context":"https://schema.org","@type":"Service","name":"Educational content development","serviceType":"Educational service","provider":{"@type":"Organization","name":"Pubrica","url":"https://pubrica.com/"},"url":"https://pubrica.com/services/educational-content-development/","description":"Curriculum, e-learning modules, assessments and multimedia built by subject content specialists and instructional designers.","areaServed":"Worldwide","audience":{"@type":"Audience","audienceType":"Researchers, PhD scholars, research institutions, medical writers and life-science teams"}},{"@context":"https://schema.org","@type":"FAQPage","mainEntity":[{"@type":"Question","name":"How do we get started?","acceptedAnswer":{"@type":"Answer","text":"Send the project details, the target audience and the objectives, and we will come back with an initial consultation and a package recommendation.\n\nIf you have an existing module, send that instead. Redesigning one against its own objectives is free and tells both of us more than a brief does."}},{"@type":"Question","name":"What do you need from us to develop the content?","acceptedAnswer":{"@type":"Answer","text":"The target audience and their prior knowledge, the learning objectives, the preferred formats, the content scope, and any guidelines or standards that apply.\n\nThe two that change the estimate most are the platform, because SCORM version determines what can be tracked, and whether the output is accredited, because accreditation carries evidence requirements the build has to satisfy."}},{"@type":"Question","name":"What types of educational content do you develop?","acceptedAnswer":{"@type":"Answer","text":"E-learning modules, course materials, instructor-led training guides, assessment tools, infographics, case studies and multimedia resources.\n\nAcross science, health, law, mathematics, history, sociology and political science, with the subject specialist drawn from the discipline rather than from a general writing pool."}},{"@type":"Question","name":"Can you handle large-scale or ongoing projects?","acceptedAnswer":{"@type":"Answer","text":"Yes — large programmes, multi-module courses and ongoing content needs, with the team scaled to the schedule.\n\nAt scale, the thing that matters is version control and a consistent objective framework across modules written by different specialists. That is a process problem more than a writing problem, and it is where multi-module builds usually come apart."}},{"@type":"Question","name":"How do you ensure quality and accuracy?","acceptedAnswer":{"@type":"Answer","text":"Content is written by subject-matter experts and designed by instructional designers, with both review passes running before delivery rather than in sequence at the end.\n\nThe subject review is the one that catches the expensive errors — a superseded guideline or a dosing interval that has changed. An instructional designer would not know to look."}},{"@type":"Question","name":"Can content be customised for specific audiences?","acceptedAnswer":{"@type":"Answer","text":"Yes — learning level, industry requirements, language and the specific educational goal.\n\nTranslation and localisation are available as an add-on, and for learning content that means adapting examples and scenarios rather than translating them, since a case that does not match local practice teaches the wrong thing."}},{"@type":"Question","name":"Do you provide revisions?","acceptedAnswer":{"@type":"Answer","text":"Yes. Every package includes feedback loops and revision rounds so the content meets the expectations and the learning goals it was built for.\n\nYou also receive editable source alongside the packaged output, so routine maintenance is something your team can do without coming back to us."}},{"@type":"Question","name":"Is the content original, and who owns it?","acceptedAnswer":{"@type":"Answer","text":"It is written from scratch and plagiarism-checked before delivery. Third-party material is either licensed or replaced.\n\nThe rights in the finished content are assigned to you. Content cannot be copyright-free — anything original is copyrighted the moment it exists — so what matters is that the copyright ends up in your hands, and it does."}}]},{"@context":"https://schema.org","@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://pubrica.com/"},{"@type":"ListItem","position":2,"name":"Services","item":"https://pubrica.com/services/"},{"@type":"ListItem","position":3,"name":"Educational content","item":"https://pubrica.com/services/educational-content-development/"}]}];

